package cl.ipvg.georegistro;
import android.os.Bundle;import android.widget.Toast;import androidx.appcompat.app.AppCompatActivity;import com.google.android.gms.maps.*;import com.google.android.gms.maps.model.*;import com.google.firebase.firestore.*;
public class MapaActivity extends AppCompatActivity implements OnMapReadyCallback{GoogleMap map;protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_mapa);((SupportMapFragment)getSupportFragmentManager().findFragmentById(R.id.map)).getMapAsync(this);}public void onMapReady(GoogleMap m){map=m;FirebaseFirestore.getInstance().collection("incidencias").orderBy("fechaCreacion",Query.Direction.DESCENDING).limit(1).get().addOnSuccessListener(q->{if(q.isEmpty()){Toast.makeText(this,"No hay incidencias.",Toast.LENGTH_SHORT).show();return;}Incidencia i=q.getDocuments().get(0).toObject(Incidencia.class);LatLng p=new LatLng(i.getLatitud(),i.getLongitud());map.addMarker(new MarkerOptions().position(p).title(i.getTitulo()).snippet(i.getCategoria()));map.moveCamera(CameraUpdateFactory.newLatLngZoom(p,16));}).addOnFailureListener(e->Toast.makeText(this,"No se pudo cargar el mapa.",Toast.LENGTH_LONG).show());}}